<template><div class="page"><div class="head"><div><h2>设备台账</h2><p>独立维护变压器、配电柜、消防、空调、供水、电梯等关键设施设备。</p></div><el-button type="primary" @click="edit()">新增设备</el-button></div><div class="filters"><el-input v-model="query.keyword" clearable placeholder="设备编号、名称、序列号或位置" @keyup.enter="load"/><el-select v-model="query.categoryId" clearable placeholder="全部分类" @change="load"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-button @click="load">查询</el-button></div><el-table :data="rows"><el-table-column prop="equipmentCode" label="设备编号"/><el-table-column prop="equipmentName" label="设备名称" min-width="140"/><el-table-column prop="categoryName" label="分类"/><el-table-column prop="systemName" label="所属系统"/><el-table-column prop="installationLocation" label="安装位置" min-width="160"/><el-table-column prop="brand" label="品牌"/><el-table-column prop="model" label="型号"/><el-table-column label="状态"><template #default="s"><el-tag>{{statusText[s.row.equipmentStatus]||s.row.equipmentStatus}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="edit(s.row)">编辑</el-button><el-button link @click="qr(s.row)">二维码</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" title="设施设备资料" width="920"><el-form label-width="105"><el-row :gutter="14"><el-col v-for="x in commonFields" :key="x.key" :span="12"><el-form-item :label="x.label"><el-select v-if="x.key==='categoryId'" v-model="form.categoryId" @change="categoryChanged"><el-option v-for="c in categories.filter((c:any)=>c.enabled)" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-else-if="x.key==='equipmentStatus'" v-model="form[x.key]"><el-option v-for="(v,k) in statusText" :key="k" :label="v" :value="k"/></el-select><el-select v-else-if="x.key==='importanceLevel'" v-model="form[x.key]"><el-option label="一般" value="NORMAL"/><el-option label="重要" value="IMPORTANT"/><el-option label="关键" value="CRITICAL"/></el-select><el-date-picker v-else-if="x.type==='date'" v-model="form[x.key]" type="date" value-format="YYYY-MM-DD"/><el-input v-else v-model="form[x.key]"/></el-form-item></el-col></el-row><div v-if="categoryFields.length" class="section">{{currentCategory?.name}}专属资料</div><el-row :gutter="14"><el-col v-for="f in categoryFields" :key="f.key" :span="12"><el-form-item :label="f.label"><el-input-number v-if="f.controlType==='NUMBER'" v-model="form.attributes[f.key]"/><el-switch v-else-if="f.controlType==='BOOLEAN'" v-model="form.attributes[f.key]"/><el-date-picker v-else-if="f.controlType==='DATE'" v-model="form.attributes[f.key]" type="date" value-format="YYYY-MM-DD"/><el-input v-else v-model="form.attributes[f.key]"><template v-if="f.unit" #append>{{f.unit}}</template></el-input></el-form-item></el-col></el-row><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="qrVisible" title="设备永久二维码" width="370"><img v-if="qrRow" class="qr" :src="`/api/v1/inspection-equipment/public-qr/${qrRow.qrToken}`"/><h3 class="center">{{qrRow?.equipmentCode}}　{{qrRow?.equipmentName}}</h3><p class="center muted">打印并张贴在设备上，扫码后自动识别该设备并进入待巡检任务。</p></el-dialog></div></template>
<script setup lang="ts">import{ref,computed,onMounted}from'vue';import{ElMessage}from'element-plus';import{inspectionEquipmentApi}from'@/api/inspectionEquipment';const rows=ref<any[]>([]),categories=ref<any[]>([]),visible=ref(false),qrVisible=ref(false),qrRow=ref<any>(),query=ref<any>({keyword:'',categoryId:null}),form=ref<any>({attributes:{}});const statusText:any={IN_USE:'在用',MAINTENANCE:'维修中',OUT_OF_SERVICE:'停用',SCRAPPED:'报废'};const commonFields=[{key:'equipmentCode',label:'设备编号'},{key:'equipmentName',label:'设备名称'},{key:'categoryId',label:'设备分类'},{key:'systemName',label:'所属系统'},{key:'installationLocation',label:'安装位置'},{key:'floorCode',label:'楼层'},{key:'areaName',label:'区域'},{key:'brand',label:'品牌'},{key:'model',label:'型号'},{key:'specification',label:'规格参数'},{key:'serialNumber',label:'出厂编号'},{key:'commissionedDate',label:'投运日期',type:'date'},{key:'responsibleDepartment',label:'责任部门'},{key:'responsiblePerson',label:'责任人'},{key:'responsiblePhone',label:'联系电话'},{key:'equipmentStatus',label:'设备状态'},{key:'importanceLevel',label:'重要等级'},{key:'maintenanceCompany',label:'维保单位'},{key:'maintenancePhone',label:'维保电话'},{key:'nextMaintenanceDate',label:'下次维保',type:'date'}];const parse=(s:any,d:any=[])=>{try{return typeof s==='string'?JSON.parse(s):s||d}catch{return d}};const currentCategory=computed(()=>categories.value.find(x=>x.id===form.value.categoryId));const categoryFields=computed(()=>parse(currentCategory.value?.baseFieldsJson));async function load(){rows.value=await inspectionEquipmentApi.list(query.value) as any}async function init(){categories.value=await inspectionEquipmentApi.categories() as any;await load()}function edit(r:any={}){form.value={id:r.id,equipmentCode:r.equipmentCode||'',equipmentName:r.equipmentName||'',categoryId:r.categoryId||null,systemName:r.systemName||'',installationLocation:r.installationLocation||'',floorCode:r.floorCode||'',areaName:r.areaName||'',brand:r.brand||'',model:r.model||'',specification:r.specification||'',serialNumber:r.serialNumber||'',commissionedDate:r.commissionedDate||'',responsibleDepartment:r.responsibleDepartment||'',responsiblePerson:r.responsiblePerson||'',responsiblePhone:r.responsiblePhone||'',equipmentStatus:r.equipmentStatus||'IN_USE',importanceLevel:r.importanceLevel||'NORMAL',maintenanceCompany:r.maintenanceCompany||'',maintenancePhone:r.maintenancePhone||'',nextMaintenanceDate:r.nextMaintenanceDate||'',attributes:parse(r.attributesJson,{}),remark:r.remark||'',enabled:r.id?!!r.enabled:true};visible.value=true}function categoryChanged(){if(!form.value.systemName)form.value.systemName=currentCategory.value?.systemName||'';form.value.attributes={}}async function save(){await inspectionEquipmentApi.save(form.value);ElMessage.success('设备资料已保存');visible.value=false;load()}function qr(r:any){qrRow.value=r;qrVisible.value=true}onMounted(init)</script>
<style scoped>.page{padding:20px}.head{display:flex;justify-content:space-between}.head h2{margin:0}.head p,.muted{color:#777}.filters{display:flex;gap:10px;background:#fff;padding:12px;margin:12px 0}.filters .el-input{max-width:380px}.section{font-weight:700;padding:10px;margin:5px 0 15px;border-bottom:1px solid #ddd}.qr{width:300px;height:300px;display:block;margin:auto}.center{text-align:center}@media(max-width:768px){.page{padding:10px}.filters{display:grid}.head{align-items:flex-start}}</style>
